import{_ as t,o as a,c as s,ae as n}from"./chunks/framework.B2ul6ABY.js";const g=JSON.parse('{"title":"Agents","description":"","frontmatter":{},"headers":[],"relativePath":"design/agents.md","filePath":"design/agents.md"}'),r={name:"design/agents.md"};function o(i,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h1><blockquote><p>Canonical design document consolidated from <code>docs/design/agents.md</code> during Stage 22. Stage 23 will reconcile detailed source anchors where needed.</p></blockquote><h2 id="agent-model" tabindex="-1">Agent Model <a class="header-anchor" href="#agent-model" aria-label="Permalink to &quot;Agent Model&quot;">​</a></h2><p><strong>The runtime drives the loop.</strong> Agents are specialized, short-lived LLM sessions invoked by the runtime at specific points. They do their job, produce output, and return control. They do not invoke themselves or each other — the support software handles sequencing, card state transitions, and agent dispatch.</p><p>This means:</p><ul><li>Agents have <strong>specific lifetimes</strong>. Planner, executor, and reviewer are scoped to their parent goal. The analyst is a special user-facing agent that lives outside any one goal.</li><li>The runtime decides <strong>what runs when</strong> — which terminal card is next, when to invoke the planner, when to run a review.</li><li>Agents can be <strong>restarted</strong> at any point — if an agent crashes or the system restarts, the runtime re-reads the cards and restores that agent&#39;s context from persisted state.</li><li>No MCP-style self-invocation — the executor doesn&#39;t call a &quot;run next task&quot; tool. The runtime feeds it tasks one at a time.</li><li>Agents <strong>cannot read or write <code>.saivage/</code> directly</strong> — all card, state, skill, and instruction access goes through MCP tools or is loaded into context by the support software.</li><li>Content that may have come from outside the project is screened by the content supervisor before it is placed in an agent&#39;s context.</li></ul><p>Each goal has <strong>three agents</strong>, all scoped to that goal&#39;s lifetime:</p><table tabindex="0"><thead><tr><th>Agent</th><th>Lifetime</th><th>Invoked when</th></tr></thead><tbody><tr><td>Planner</td><td>Goal activation → done</td><td>Initial, all tasks done, after review rejection, on failure</td></tr><tr><td>Executor</td><td>Goal activation → done</td><td>For each terminal card, sequentially</td></tr><tr><td>Reviewer</td><td>On demand → goal done</td><td>When planner declares done; on re-review after corrections</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RT((Runtime))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RT --&gt; |&quot;goal active&quot;| PL[Planner]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PL --&gt; |creates cards| RT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RT --&gt; |&quot;card ready&quot;| EX[Executor]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    EX --&gt; |results| RT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RT --&gt; |&quot;all done&quot;| PL2[Planner]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PL2 --&gt; |&quot;declare done&quot;| RV[Reviewer]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RV --&gt; |pass| RT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RV --&gt; |fail| PL2</span></span></code></pre></div><h3 id="visible-execution-style" tabindex="-1">Visible execution style <a class="header-anchor" href="#visible-execution-style" aria-label="Permalink to &quot;Visible execution style&quot;">​</a></h3><p>Every agent response that includes tool calls must begin with a short explanation of what the agent is about to do. This keeps the conversation trace readable and lets operators understand agent intent without expanding every tool call.</p><hr><h2 id="analyst-the-chat-agent" tabindex="-1">Analyst (the chat agent) <a class="header-anchor" href="#analyst-the-chat-agent" aria-label="Permalink to &quot;Analyst (the chat agent)&quot;">​</a></h2><p><strong>Interface</strong>: Chat (Telegram, web UI, CLI). This is the agent users talk to.</p><p><strong>Role</strong>: The single gateway for managing cards <strong>and</strong> controlling execution. The analyst is a conversational agent whose tools cover card CRUD, execution control, and inspection. Its system prompt includes the project card context so it always knows the global constraints.</p><p><strong>Lifetime</strong>: Always available. Not scoped to a goal. Persists across the entire session. Survives runtime restarts via chat log persistence.</p><p>Tools — card management:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>create_card</code></td><td>Create a card at any level</td></tr><tr><td><code>edit_card</code></td><td>Edit fields (title, description, acceptance…)</td></tr><tr><td><code>move_card</code></td><td>Re-parent a card in the tree</td></tr><tr><td><code>delete_card</code></td><td>Remove a card (and its children)</td></tr><tr><td><code>add_note</code></td><td>Append a note to a card&#39;s activity log</td></tr><tr><td><code>list_cards</code></td><td>Query/filter the card tree</td></tr><tr><td><code>get_card</code></td><td>Read full card details (including notes)</td></tr></tbody></table><p>Tools — execution control:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>pause_runtime</code></td><td>Globally pause new planner/executor/reviewer dispatch</td></tr><tr><td><code>resume_runtime</code></td><td>Resume dispatch after a global pause</td></tr><tr><td><code>abort_goal</code></td><td>Abort a goal — marks it and children <code>cancelled</code></td></tr><tr><td><code>restart_card</code></td><td>Re-queue a done/failed task card → <code>backlog</code></td></tr><tr><td><code>restart_goal</code></td><td>Reset a goal: cancel running children, clear the plan diary, re-queue the goal → <code>backlog</code> so the planner starts fresh when it is next activated</td></tr><tr><td><code>kill_process</code></td><td>Kill a running external process</td></tr></tbody></table><p>Tools — inspection:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>get_card</code></td><td>Full card details, notes, attachments</td></tr><tr><td><code>list_cards</code></td><td>Query/filter (by status, type, parent, etc.)</td></tr><tr><td><code>get_plan_diary</code></td><td>Read a goal&#39;s plan card diary + review results</td></tr><tr><td><code>get_card_output</code></td><td>Tail output of a card&#39;s running/completed processes</td></tr><tr><td><code>get_tree</code></td><td>Show the full or partial card tree</td></tr><tr><td><code>get_status</code></td><td>Runtime status — active cards, running processes, queue</td></tr></tbody></table><p>The analyst can inspect everything: cards at any level, plan diaries (including reviewer assessments stored there), execution output, running processes, and system state. It uses this to answer user questions about what&#39;s happening, what was tried, and why.</p><p>Typical interactions:</p><ul><li><strong>User</strong>: &quot;I want to try a caching layer for the search index&quot; → analyst finds/creates the right goal, creates a goal with acceptance criteria, asks the user to confirm.</li><li><strong>User</strong>: &quot;Change the project constraint to max 2-week experiments&quot; → analyst edits the project card.</li><li><strong>User</strong>: &quot;Stop the synonym expansion goal, it&#39;s going nowhere&quot; → analyst calls <code>abort_goal</code> on the synonym expansion goal.</li><li><strong>User</strong>: &quot;Pause everything until I check the data&quot; → analyst calls <code>pause_runtime</code>, which stops new agent dispatch but does not automatically kill already-running processes.</li><li><strong>User</strong>: &quot;What is the executor doing right now?&quot; → analyst calls <code>get_status</code> and <code>get_card_output</code> to describe the current work and its output.</li></ul><p>The analyst never performs terminal task work — it manages cards, controls execution, and inspects runtime state.</p><hr><h2 id="planner-per-goal-agent" tabindex="-1">Planner (per-goal agent) <a class="header-anchor" href="#planner-per-goal-agent" aria-label="Permalink to &quot;Planner (per-goal agent)&quot;">​</a></h2><p><strong>Lifetime</strong>: Scoped to its parent goal. Created when the goal becomes <code>active</code> and retained until the goal reaches a terminal state. If the system restarts, the runtime restores the planner&#39;s context from the plan card diary and persisted runtime state.</p><p><strong>Invoked by the runtime</strong> at four points (see card model):</p><ol><li><strong>Initial decomposition</strong> — goal becomes active.</li><li><strong>All tasks complete</strong> — all sibling cards reach done/failed.</li><li><strong>After review rejection</strong> — reviewer says criteria not met.</li><li><strong>On failure</strong> — a sibling card fails.</li></ol><p>Each invocation receives the plan card (diary) as context, so the planner sees its full history of decisions.</p><p><strong>Role</strong>: Decomposes goals, reads review assessments, handles failures. At the project level, this is the regular planner for the project card (depth 0): it decides strategic direction and proposes new top-level goals when the system is idle.</p><p><strong>Configurable instructions</strong>: Each planner reads:</p><ol><li>Its own plan card (diary of previous decisions).</li><li>The parent goal&#39;s description and acceptance criteria.</li><li>The project card&#39;s context and constraints.</li><li>An optional user-editable instruction file (<code>.saivage/instructions/planner.md</code> for the depth-0 planner, or a field on the goal card for deeper levels). The support software loads or links these instructions into the planner&#39;s context; the planner does not read <code>.saivage/</code> directly.</li></ol><p>The depth-0 planner instructions are where the user defines the overall strategy:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Planner Instructions</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Strategy</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Prioritize goals that explore new approaches over</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  re-running existing ones with minor tweaks.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> When a goal fails, try once with an adjusted approach before</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  escalating to the user.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do not create more than 3 goals in backlog at any time.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## When idle</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Review completed goals and look for patterns.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Propose follow-up goals for the best-performing results.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Identify gaps in coverage.</span></span></code></pre></div><p>The depth-0 planner can be <strong>enabled or disabled</strong>. When disabled, only user-originated goals exist and the system idles when all work is done.</p><p><strong>Interface</strong>: The planner emits structured card mutation requests. The runtime applies them through the same card MCP and validation path used by the analyst. It doesn&#39;t have direct card-write access; this ensures every card goes through the same structuring logic.</p><hr><h2 id="executor-per-goal-agent" tabindex="-1">Executor (per-goal agent) <a class="header-anchor" href="#executor-per-goal-agent" aria-label="Permalink to &quot;Executor (per-goal agent)&quot;">​</a></h2><p><strong>Lifetime</strong>: Scoped to its parent goal. Created when the first terminal card under that goal is ready to execute. Persists until all terminal cards are complete (or the goal is cancelled/failed).</p><p><strong>Invoked by the runtime</strong> for each terminal card in sequence. The runtime determines the order based on <code>depends_on</code> and <code>priority</code>. The executor does not choose what to run next — it receives a card, does the work, returns results.</p><p><strong>Execution is sequential by default</strong> — one terminal card at a time. Besides the analyst, the runtime runs only one agent at a time. Planner, executor, and reviewer invocations are not parallel unless explicitly configured as a future extension.</p><p><strong>Role</strong>: Runs terminal cards — the actual leaf work. The card&#39;s type tells the executor what kind of work is expected:</p><table tabindex="0"><thead><tr><th>Terminal type</th><th>Executor behavior</th></tr></thead><tbody><tr><td>Architecture</td><td>Produce design docs, diagrams, API specs</td></tr><tr><td>Code</td><td>Write, modify, or refactor code</td></tr><tr><td>Test</td><td>Write and run tests, report results</td></tr><tr><td>Doc</td><td>Write documentation, guides, runbooks</td></tr><tr><td>Data</td><td>Acquire, clean, transform data</td></tr><tr><td>Research</td><td>Investigate, benchmark, review literature</td></tr><tr><td>Ops</td><td>Deploy, configure, monitor, fix infrastructure</td></tr></tbody></table><p>For each terminal card:</p><ol><li>Receives the card from the runtime.</li><li>Reads the card&#39;s description and acceptance criteria.</li><li>Reads unhandled notes/directives and marks them handled.</li><li>Does the work (shell commands, file edits, scripts, etc.).</li><li>Captures results (metrics, artifacts, attachments).</li><li>Returns results to the runtime, which transitions the card to <code>done</code> or <code>failed</code>.</li></ol><p>The executor has tools for doing work (shell, filesystem, git, etc.) but does <strong>not</strong> have tools for card management or self-dispatch. It cannot create cards, choose the next task, or invoke other agents.</p><h3 id="external-command-execution-model" tabindex="-1">External command execution model <a class="header-anchor" href="#external-command-execution-model" aria-label="Permalink to &quot;External command execution model&quot;">​</a></h3><p>All external commands (shell, scripts, training runs, etc.) are launched as <strong>processes</strong> and executed asynchronously. Tasks are the low-level terminal cards; processes are external programs launched while executing those cards. The MCP layer provides:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>start_process</code></td><td>Start a command asynchronously. Returns a process ID. Output is streamed to a file.</td></tr><tr><td><code>wait_process</code></td><td>Wait for a process to finish, up to a timeout. If the timeout is reached, the process is <strong>not killed</strong> — the return says it&#39;s still running. The agent decides whether to kill or let it continue.</td></tr><tr><td><code>start_and_wait</code></td><td>Shortcut: <code>start_process</code> + <code>wait_process</code> in one call.</td></tr><tr><td><code>tail_output</code></td><td>Get the last N lines of a process&#39;s output file.</td></tr><tr><td><code>kill_process</code></td><td>Kill a running process by ID.</td></tr><tr><td><code>list_processes</code></td><td>List running/completed processes for the current card.</td></tr><tr><td><code>download_file</code></td><td>Download a file and run it through content supervision before it can be used.</td></tr></tbody></table><p>Key properties:</p><ul><li>Output is always saved to a file, so it survives agent restarts and can be inspected later (by the analyst, planner, or reviewer).</li><li><code>start_and_wait</code> is the common case — run a command and get the result. But if the command takes longer than expected, the agent isn&#39;t stuck: it gets a &quot;still running&quot; response and can decide to wait more, kill, or move on.</li><li>Long-running processes (training, benchmarks) are started with <code>start_process</code> and polled with <code>tail_output</code>.</li><li>When the planner is re-invoked after all tasks complete, the runtime includes the list of still-running processes so the planner can decide what to do with them.</li></ul><hr><h2 id="reviewer-per-goal-agent" tabindex="-1">Reviewer (per-goal agent) <a class="header-anchor" href="#reviewer-per-goal-agent" aria-label="Permalink to &quot;Reviewer (per-goal agent)&quot;">​</a></h2><p><strong>Lifetime</strong>: Scoped to its parent goal. Invoked the first time the planner declares the goal done. Recalled for every subsequent re-review (when the planner adds correction cards and they complete, and the planner declares done again). Follow-up review calls in the same goal return to the same reviewer conversation, so the reviewer can compare new corrective results with its earlier findings.</p><p><strong>Invoked by the runtime</strong> when the planner declares the goal done.</p><p><strong>Role</strong>: Checks whether the goal&#39;s acceptance criteria were met. For each review:</p><ol><li>Reads the parent goal&#39;s acceptance criteria.</li><li>Reads results, metrics, and artifacts from sibling cards.</li><li>Produces a structured assessment: pass/fail, what was achieved, what&#39;s missing.</li><li>Returns the assessment to the runtime, which <strong>appends it to the plan card</strong> (the planner&#39;s diary).</li></ol><p>If the review <strong>passes</strong>, the goal transitions to <code>done</code>.</p><p>If the review <strong>fails</strong>, the planner is re-invoked. It reads the review from the plan card, creates correction cards, and the cycle continues.</p><p>The reviewer does NOT decide what happens next — it only assesses. The planner reads the review from its diary and decides.</p>`,63)])])}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
